  (gen_random_uuid(), 'bksq-bonanza-a36---a36tc-professional', 'Reference Tables', 'reference_table', '[{"id":"reference-tables","title":"Reference Tables","items":[{"id":"reference-tables-a36-normally-aspirated-0","label":"A36 Normally Aspirated","notes":"data:table/json,[[\\"Specification\\",\\"Value\\"],[\\"Maximum Cruising Speed\\",\\"174 ktas\\"],[\\"Normal Cruising Speed\\",\\"169 ktas\\"],[\\"Economy Cruising Speed\\",\\"143 ktas\\"],[\\"Takeoff Distance\\",\\"2,040 ft\\"],[\\"Takeoff Ground Roll\\",\\"962 ft\\"],[\\"Landing Distance\\",\\"1,450 ft\\"],[\\"Landing Ground Roll\\",\\"833 ft\\"],[\\"Normal Range\\",\\"716 nm\\"],[\\"Maximum Range\\",\\"920 nm\\"],[\\"Rate of Climb\\",\\"1,230 ft/min\\"],[\\"Service Ceiling\\",\\"18,500 ft\\"],[\\"Empty Weight\\",\\"2,145 lbs\\"],[\\"Max Ramp Weight\\",\\"3,650 lbs\\"],[\\"Max Takeoff Weight\\",\\"3,600 lbs\\"],[\\"Max Landing Weight\\",\\"3,600 lbs\\"],[\\"Useful Load\\",\\"1,455 lbs\\"],[\\"Usable Fuel Weight\\",\\"445 lbs\\"],[\\"Full Fuel Payload\\",\\"1,010 lbs\\"],[\\"Maximum Operating Temp.\\",\\"+53°C\\"],[\\"Minimum Operating Temp.\\",\\"-54°C\\"]]"},{"id":"reference-tables-a36tc--turbocharged-with-tip-tanks--1","label":"A36TC (Turbocharged with Tip Tanks)","notes":"data:table/json,[[\\"Specification\\",\\"Value\\"],[\\"Maximum Cruising Speed\\",\\"216 ktas\\"],[\\"Normal Cruising Speed\\",\\"194 ktas\\"],[\\"Economy Cruising Speed\\",\\"151 ktas\\"],[\\"Takeoff Distance\\",\\"2,015 ft\\"],[\\"Takeoff Ground Roll\\",\\"958 ft\\"],[\\"Landing Distance\\",\\"1,450 ft\\"],[\\"Landing Ground Roll\\",\\"833 ft\\"],[\\"Normal Range\\",\\"1,005 nm\\"],[\\"Maximum Range\\",\\"1,280 nm\\"],[\\"Rate of Climb\\",\\"1,660 ft/min\\"],[\\"Service Ceiling\\",\\"25,000 ft\\"],[\\"Empty Weight\\",\\"2,214 lbs\\"],[\\"Max Ramp Weight\\",\\"4,080 lbs\\"],[\\"Max Takeoff Weight\\",\\"4,030 lbs\\"],[\\"Max Landing Weight\\",\\"4,030 lbs\\"],[\\"Useful Load\\",\\"1,815 lbs\\"],[\\"Usable Fuel Weight\\",\\"625 lbs\\"],[\\"Full Fuel Payload\\",\\"1,190 lbs\\"],[\\"Maximum Operating Temp.\\",\\"+53°C\\"],[\\"Minimum Operating Temp.\\",\\"-54°C\\"]]"},{"id":"reference-tables-engine-limits---a36-2","label":"Engine Limits — A36","notes":"data:table/json,[[\\"Specification\\",\\"Value\\"],[\\"Engine Speed\\",\\"2,700 RPM\\"],[\\"Cylinder Head Temperature\\",\\"460°F (238°C)\\"],[\\"Exhaust Gas Temperature\\",\\"1650°F (900°C)\\"],[\\"Oil Temperature\\",\\"240°F (116°C)\\"],[\\"Oil Pressure\\",\\"30 PSI (min.) 100 PSI (max.)\\"],[\\"Fuel Pressure\\",\\"1.5 PSI (min.) 17.5 PSI (max.)\\"],[\\"Manifold Pressure\\",\\"29.6 inHg\\"]]"},{"id":"reference-tables-engine-limits---turbocharger-limitations-3","label":"Engine Limits — Turbocharger Limitations","notes":"data:table/json,{\\"headers\\":[\\"Specification\\",\\"Value\\"],\\"rows\\":[[\\"Critical Altitude\\",\\"19,000 ft (varies with throttleand atmospheric conditions)\\"],[\\"Turbine Inlet Temperature\\",\\"1650°F (900°C)\\"],[\\"Maximum Turbine RPM\\",\\"125,000 RPM\\"]],\\"postNote\\":\\"DO NOT fully retard throttle above critical altitude. Engine combustion may cease. NOTE: The A36TC is a “turbonormalized” aircraft, meaning that the turbocharger and wastegate work together to provide pressurized air at sea-level pressures to the intake manifold. This is in contrast to other turbocharging configurations, which provide air boosted to pressures exceeding 29.9 inHg to the manifold. ● Do not engage starter for more than 30 seconds in any 4-minute period. ● Do not take-off when fuel quantity gauges indicate in the yellow arc, or with less than 13 gallons usable in each main tank. ● Maximum slip duration: 30 seconds. ● Do not attempt to fully retract landing gear with manual hand crank handle. Doing so may cause damage to worm gear shaft. ● Avoid cooling cylinders at rates greater than 60°F (33°C) per minute.\\"}"},{"id":"reference-tables-a36-charts--takeoff---cruise-climb---cruise----take-off-power--full-throttle----standard-day--isa----no-wind-4",