  (gen_random_uuid(), 'bksq-baron-professional', 'Reference Tables', 'reference_table', '[{"id":"reference-tables","title":"Reference Tables","items":[{"id":"reference-tables-normally-aspirated-b58---b58-normally-aspirated-0","label":"Normally Aspirated B58 — B58 Normally Aspirated","notes":"data:table/json,[[\\"Specification\\",\\"Value\\"],[\\"Maximum Cruising Speed\\",\\"198 ktas\\"],[\\"Normal Cruising Speed\\",\\"180 ktas\\"],[\\"Economy Cruising Speed\\",\\"153 ktas\\"],[\\"Takeoff Distance\\",\\"2,345 ft\\"],[\\"Takeoff Ground Roll\\",\\"1,373 ft\\"],[\\"Landing Distance\\",\\"2,428 ft\\"],[\\"Landing Ground Roll\\",\\"1,378 ft\\"],[\\"Normal Range\\",\\"1,013 nm\\"],[\\"Maximum Range\\",\\"1,276 nm\\"],[\\"Rate of Climb\\",\\"1,610 ft/min\\"],[\\"Service Ceiling\\",\\"20,668 ft\\"],[\\"Empty Weight\\",\\"3,120 lbs\\"],[\\"Max Ramp Weight\\",\\"5,524 lbs\\"],[\\"Max Takeoff Weight\\",\\"5,500 lbs\\"],[\\"Max Landing Weight\\",\\"5,400 lbs\\"],[\\"Useful Load\\",\\"2,400 lbs\\"],[\\"Usable Fuel Weight\\",\\"996 lbs\\"],[\\"Full Fuel Payload\\",\\"1,404 lbs\\"],[\\"Maximum Operating Temp.\\",\\"+53°C\\"],[\\"Minimum Operating Temp.\\",\\"-54°C\\"]]"},{"id":"reference-tables-turbocharged-b58tc---b58p---b58tc---b58p-turbocharged-------denotes-b58p-model--1","label":"Turbocharged B58TC & B58P — B58TC & B58P Turbocharged — ( * Denotes B58P model)","notes":"data:table/json,[[\\"Specification\\",\\"Value\\"],[\\"Maximum Cruising Speed\\",\\"261 ktas\\"],[\\"Normal Cruising Speed\\",\\"245 ktas\\"],[\\"Economy Cruising Speed\\",\\"166 ktas\\"],[\\"Takeoff Distance\\",\\"2,643 ft\\"],[\\"Takeoff Ground Roll\\",\\"1,555 ft\\"],[\\"Landing Distance\\",\\"2,490 ft\\"],[\\"Landing Ground Roll\\",\\"1,440 ft\\"],[\\"Normal Range\\",\\"1,186 nm\\"],[\\"Maximum Range\\",\\"1,438 nm\\"],[\\"Rate of Climb\\",\\"1,850 ft/min\\"],[\\"Service Ceiling\\",\\"25,000 ft\\"],[\\"Empty Weight\\",\\"3,788 lbs*4,010 lbs*\\"],[\\"Max Ramp Weight\\",\\"6,240 lbs\\"],[\\"Max Takeoff Weight\\",\\"6,200 lbs\\"],[\\"Max Landing Weight\\",\\"6,200 lbs\\"],[\\"Useful Load\\",\\"2,452 lbs*2,230 lbs*\\"],[\\"Usable Fuel Weight\\",\\"1,176 lbs\\"],[\\"Full Fuel Payload\\",\\"1,422 lbs*1,200 lbs*\\"],[\\"Maximum Operating Temp.\\",\\"+53°C\\"],[\\"Minimum Operating Temp.\\",\\"-54°C\\"]]"},{"id":"reference-tables-engine-limits---engine-limitations-2","label":"Engine Limits — Engine Limitations","notes":"data:table/json,[[\\"Engine Speed\\",\\"2,700 RPM\\"],[\\"Cylinder Head Temperature\\",\\"460°F (238°C)\\"],[\\"Exhaust Gas Temperature\\",\\"1650°F (900°C)\\"],[\\"Oil Temperature\\",\\"240°F (116°C)\\"],[\\"Oil Pressure\\",\\"30 PSI (min.) 100 PSI (max.)\\"],[\\"Fuel Pressure\\",\\"1.5 PSI (min.) 17.5 PSI (max.)\\"],[\\"Manifold Pressure\\",\\"29.6 inHg / 39.5 inHg (Turbocharged)\\"]]"},{"id":"reference-tables-engine-limits---turbocharger-limitations-3","label":"Engine Limits — Turbocharger Limitations","notes":"data:table/json,{\\"headers\\":[\\"Critical Altitude\\",\\"20,000 ft(varies with throttle and atmospheric conditions)\\"],\\"rows\\":[[\\"Turbine Inlet Temperature\\",\\"1650°F (900°C)\\"],[\\"Maximum Turbine RPM\\",\\"125,000 RPM\\"]],\\"postNote\\":\\"DO NOT fully retard throttle above critical altitude. Engine combustion may cease. NOTE: The 58TC and 58P are “turbocharged” aircraft, as opposed to a “turbonormalized” aircraft, meaning that the engine is capable of operating at intake manifold pressures greater than that of sea level (29.9 inHg). ● Do not engage starter for more than 30 seconds in any 4-minute period. ● Do not take off when fuel quantity gauges indicate in the yellow arc, or with less than 20 gallons in each main tank. ● Maximum slip duration: 30 seconds. ● Do not attempt to fully retract landing gear with manual hand crank handle. Doing so may cause damage to worm gear shaft. ● Avoid cooling cylinders at rates greater than 60°F (33°C) per minute.\\"}"},{"id":"reference-tables-b58na-charts--takeoff---cruise-climb---cruise----take-off-